#[derive(Debug)]
pub struct AccessControlDirectoryClient {
    get_role: NativeRequestHandle<AccessControlDirectoryGetRole>,
    list_roles: NativeRequestHandle<AccessControlDirectoryListRoles>,
    list_subject_roles: NativeRequestHandle<AccessControlDirectoryListSubjectRoles>,
}
impl AccessControlDirectoryClient {
    pub fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_dependencies(dependencies)
    }

    pub async fn get_role(&self, request: GetRoleRequest) -> Result<GetRoleResponse, AccessControlDirectoryGetRoleInvocationError> {
        self.get_role.invoke(GET_ROLE_OPERATION, request).await
            .map_err(AccessControlDirectoryGetRoleInvocationError::Runtime)?
            .map_err(AccessControlDirectoryGetRoleInvocationError::Domain)
    }

    pub async fn get_role_with_context(&self, context: InvocationContext, request: GetRoleRequest) -> Result<GetRoleResponse, AccessControlDirectoryGetRoleInvocationError> {
        self.get_role.invoke_with_context(GET_ROLE_OPERATION, context, request).await
            .map_err(AccessControlDirectoryGetRoleInvocationError::Runtime)?
            .map_err(AccessControlDirectoryGetRoleInvocationError::Domain)
    }

    pub async fn list_roles(&self, request: ListRolesRequest) -> Result<ListRolesResponse, AccessControlDirectoryListRolesInvocationError> {
        self.list_roles.invoke(LIST_ROLES_OPERATION, request).await
            .map_err(AccessControlDirectoryListRolesInvocationError::Runtime)?
            .map_err(AccessControlDirectoryListRolesInvocationError::Domain)
    }

    pub async fn list_roles_with_context(&self, context: InvocationContext, request: ListRolesRequest) -> Result<ListRolesResponse, AccessControlDirectoryListRolesInvocationError> {
        self.list_roles.invoke_with_context(LIST_ROLES_OPERATION, context, request).await
            .map_err(AccessControlDirectoryListRolesInvocationError::Runtime)?
            .map_err(AccessControlDirectoryListRolesInvocationError::Domain)
    }

    pub async fn list_subject_roles(&self, request: ListSubjectRolesRequest) -> Result<ListSubjectRolesResponse, AccessControlDirectoryListSubjectRolesInvocationError> {
        self.list_subject_roles.invoke(LIST_SUBJECT_ROLES_OPERATION, request).await
            .map_err(AccessControlDirectoryListSubjectRolesInvocationError::Runtime)?
            .map_err(AccessControlDirectoryListSubjectRolesInvocationError::Domain)
    }

    pub async fn list_subject_roles_with_context(&self, context: InvocationContext, request: ListSubjectRolesRequest) -> Result<ListSubjectRolesResponse, AccessControlDirectoryListSubjectRolesInvocationError> {
        self.list_subject_roles.invoke_with_context(LIST_SUBJECT_ROLES_OPERATION, context, request).await
            .map_err(AccessControlDirectoryListSubjectRolesInvocationError::Runtime)?
            .map_err(AccessControlDirectoryListSubjectRolesInvocationError::Domain)
    }
}

impl CapabilityClient for AccessControlDirectoryClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            get_role: dependencies.one::<AccessControlDirectoryGetRole>()?,
            list_roles: dependencies.one::<AccessControlDirectoryListRoles>()?,
            list_subject_roles: dependencies.one::<AccessControlDirectoryListSubjectRoles>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for AccessControlDirectoryClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    get_role: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<AccessControlDirectoryGetRole>()?,
                    list_roles: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<AccessControlDirectoryListRoles>()?,
                    list_subject_roles: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<AccessControlDirectoryListSubjectRoles>()?,
                    },
                ))
            })
            .collect()
    }
}

